/** Render measured losses, unavailable evidence and the exact registered denominator. */
import type { Report } from './place-report.types.ts';
export function renderPlaceReport(r: Report): string {
  const c = r.coverage, f = r.floor;
  return ['# Sourced place conformance', '',
    'Generated by `npm run benchmark:place -- --json benchmark/results/place.json --md docs/PLACE_BENCHMARK.md`.', '',
    `Fixture: \`${r.fixtureHash}\`. Report: \`${r.sha256}\`. Effective source: \`${r.source.sha256}\`.`, '',
    `Corpus: **${r.corpus.status}**${r.corpus.detail ? ` — ${r.corpus.detail}` : ''}. ${r.census.questions} original questions; ${r.census.turns} source turns audited.`, '',
    '## Scope and source qualification', '',
    'No number here is a LoCoMo score. These are original host-asserted annotations of named places in the separately licensed conversation corpus. The location and movement questions address an explicit reporting-session annotation index, not the historical time of a trip. Source observations retain minute precision; exact query points identify the supplied reporting index. The one residence with an unknown end remains unknown.', '',
    'Coordinates are verbatim sourced Wikidata CC0 point proxies. Rounded distances use the native spherical IUGG mean-radius model, in metres, between those proxies. They do not measure traveled routes, exact persona positions, or ellipsoidal distance. Nearby and cell-boundary questions concern gazetteer geometry alone.', '',
    '| Audited mentions | Grounded | Ungrounded | Ambiguous | Grounded fraction | Personas with positions | Position assertions |',
    '|---:|---:|---:|---:|---:|---:|---:|',
    `| ${c.mentionSites} | ${c.grounded} | ${c.ungrounded} | ${c.ambiguous} | ${(c.grounded / c.mentionSites).toFixed(6)} | ${c.personas} | ${c.positions} |`, '',
    '| Admission condition | Registered threshold | Observed |', '|---|---:|---:|',
    `| Grounded fraction | ≥ ${f.minimumGroundedFraction} | ${f.groundedFraction} |`,
    `| Conversations with location questions | ≥ ${f.minimumLocationConversations} | ${f.locationConversations} |`,
    `| Conversations with movement questions | ≥ ${f.minimumMovementConversations} | ${f.movementConversations} |`,
    `| Unsourced entries | ≤ ${f.maximumUnsourcedEntries} | ${f.unsourcedEntries} |`, '',
    '## Equal-budget methods', '',
    `Hash embedding dimensions ${r.registration.dims}; candidate pool ${r.registration.candidatePool}; final k ${r.registration.k}; minimum score ${r.registration.minScore}. All comparable rows share one projection per conversation and a source-occurrence-id ordering for score ties. The full finite source pool precedes eligibility. Hash embeddings measure lexical retrieval mechanics, not live embedding quality.`, '',
    'The oracle reads privileged audited annotations and native geometry/time kernels; it never reads the question expectations. The seeded control draws one uniformly selected entry for every question, including kinds that cannot be answered by one entry. Ordinary retrieval chooses the first grounded mention among its top-k turns. The temporal baseline receives the event session instant from the instrument because it cannot join two series. Both baselines record no-geometry on distance/proximity questions. Temporal unknown-validity and no-match losses are retained.', '',
    'The three registered place backends retain independent rows. An absent implementation or corpus is never a passing zero. Exactness uses the complete registered per-kind denominator; correct refusals are scored by the same exact equality as answers.', '',
    '| Method | Backend | Kind | Planned | Measured | Passed | Incorrect | Failed | Missing | Unavailable | Exactness |',
    '|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|',
    ...r.summaries.map(s => `| ${s.row} | ${s.backend} | ${s.kind} | ${s.counts.planned} | ${s.counts.measured} | ${s.counts.passed} | ${s.counts.incorrect} | ${s.counts.failed} | ${s.counts.implementationMissing} | ${s.counts.unavailable} | ${s.exactness === null ? 'unmeasured' : s.exactness.toFixed(6)} |`), '',
    `Seed ${r.registration.seed}: ${r.randomFloor.passed} control successes; analytic expected successes ${r.randomFloor.expectedPasses.toFixed(6)}, preregistered band [${r.randomFloor.lowerPasses.toFixed(6)}, ${r.randomFloor.upperPasses.toFixed(6)}] (four standard deviations plus one-question slack). Band holds: ${r.randomFloor.holds}.`, '',
    '## Refusals and scorer controls', '',
    '| Spatial fixture | Expected | Observed | Passed |', '|---|---|---|---|',
    ...r.gateFixtures.map(g => `| ${g.path} | ${g.expectedCode} | ${g.actualCode ?? 'none'} | ${g.passed} |`), '',
    `Counterfeit answers rejected: ${r.wrongControls.filter(c => c.rejected).length}/${r.wrongControls.length}. Unmatched position joins: ${r.refusals.unmatchedJoins}.`, '',
    '| Refusal code | Count |', '|---|---:|', ...Object.entries(r.refusals.byCode).sort().map(([code, n]) => `| ${code} | ${n} |`), '',
    '| Underlying cause, including the exercised prefix gate | Count |', '|---|---:|', ...Object.entries(r.refusals.byCause).sort().map(([code, n]) => `| ${code} | ${n} |`), '',
    '## Non-regression and limits', '',
    `Canonical recall SHA-256: \`${r.locomo.recallSha256}\`. Canonical QA SHA-256: \`${r.locomo.qaSha256}\`. These reports remain unchanged; this instrument does not relabel category 1–4 results.`, '',
    `Physical live requests: ${r.liveRequests}. The configuration envelope honestly records no executed provider stack; this is separate from a measured keyless row. Default routing stays **${r.default}**. Live extraction and model quality are unmeasured. Timing is excluded from this canonical report; the registered ${r.scale.entries}-entry/${r.scale.probes}-probe scale experiment has a ${r.scale.targetP95Ms} ms warm p95 target.`, '',
  ].join('\n');
}
